-- =============================================================================
-- 450 — LE CAHIER D'EXERCICES DE TLE (partie 15)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 450 --niveau Tle --matieres enseignement-scientifique,nsi --suffixe 15 > supabase/contenu/450_exercices_tle_15.sql
--
-- 108 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   enseignement-scientifique.k147  24 exercices · 8 chapitres
--   enseignement-scientifique.k148  24 exercices · 8 chapitres
--   nsi.k179                30 exercices · 10 chapitres
--   nsi.k180                30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('c7199117-4288-5ea0-96ae-042932b4df27'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"D’où vient l’énergie du monde ?","competence":"lire-graphique","situation":"Chaque année, le monde consomme environ 600 EJ d’énergie (l’exajoule, EJ, est une unité d’énergie). Le graphique montre d’où elle vient.","documents":[{"id":"mix","type":"graphique","forme":"barres-h","titre":"Part de chaque source dans l’énergie mondiale","categories":["Pétrole","Charbon","Gaz","Hydraulique","Nucléaire","Biomasse et autres"],"series":[{"nom":"Part","valeurs":[30,27,23,7,4,9]}],"axeY":{"titre":"Part de l’énergie consommée","unite":"en %","min":0,"max":35,"pas":5},"valeurs":true,"source":"Chiffres arrondis, ordre de grandeur récent"}],"questions":[{"enonce":"Touche la source d’énergie la plus utilisée dans le monde.","aide":"Cherche la barre la plus longue.","type":"zone","document":"mix","multiple":false},{"enonce":"Quelle part de l’énergie mondiale vient des trois combustibles fossiles (pétrole, charbon, gaz), en % ?","aide":"Additionne les trois barres concernées.","type":"nombre","unite":"%"},{"enonce":"Sur les 600 EJ consommés, combien viennent des combustibles fossiles, en EJ ?","aide":"Prends 80 % de 600 : multiplie par 0,80.","type":"nombre","unite":"EJ"},{"enonce":"Pourquoi cette part pèse-t-elle lourd dans le réchauffement ?","aide":"Pense à ce que devient le carbone quand on brûle un combustible.","type":"choix","options":[{"id":"a","texte":"Leur extraction refroidit les océans et dérègle les courants"},{"id":"b","texte":"Leur combustion consomme le CO₂ que l’air contenait déjà"},{"id":"c","texte":"Leur combustion détruit la couche d’ozone de la haute atmosphère"},{"id":"d","texte":"Leur combustion libère du CO₂ stocké sous terre depuis très longtemps"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"Le **pétrole** fournit environ 30 % de l’énergie mondiale : c’est la barre la plus longue."},{"cle":{"type":"nombre","valeur":80,"tolerance":0},"affichage":"80 %","explication":"30 + 27 + 23 = **80 %** : les combustibles fossiles fournissent encore environ quatre cinquièmes de l’énergie."},{"cle":{"type":"nombre","valeur":480,"tolerance":0},"affichage":"480 EJ","explication":"0,80 × 600 = **480 EJ**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Brûler un combustible fossile **libère du CO₂** stocké depuis des millions d’années : il s’ajoute à celui de l’atmosphère."}]$ex$::jsonb),
  ('c7199117-4288-5ea0-96ae-042932b4df27'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le budget carbone de la planète","competence":"modeliser","situation":"La hausse de la température moyenne est proportionnelle au CO₂ cumulé émis depuis 1850 (valeur simplifiée pour l’exercice). Depuis 1850, environ 2 500 Gt de CO₂ ont déjà été émis. Aujourd’hui, le monde émet environ 40 Gt de CO₂ par an.","documents":[{"id":"budget","type":"graphique","forme":"courbe","titre":"Hausse de température selon le CO₂ cumulé","categories":["0","1 000","2 000","3 000","4 000"],"series":[{"nom":"Hausse de température","valeurs":[0,0.5,1,1.5,2],"teinte":"encre"}],"axeY":{"titre":"Hausse de température","unite":"en °C","min":0,"max":2,"pas":0.5},"axeX":{"titre":"CO₂ cumulé émis depuis 1850 (Gt)"},"source":"Modèle simplifié, écrit pour l’exercice"}],"questions":[{"enonce":"Touche la valeur de CO₂ cumulé qui correspond à une hausse de 1,5 °C.","aide":"Pars de 1,5 °C sur l’axe vertical, puis regarde la graduation en dessous.","type":"zone","document":"budget","multiple":false},{"enonce":"Quel budget reste-t-il à émettre avant d’atteindre +1,5 °C, en Gt de CO₂ ?","aide":"Budget total moins ce qui est déjà émis.","type":"nombre","unite":"Gt"},{"enonce":"À 40 Gt par an, en combien d’années ce budget serait-il épuisé ?","aide":"Divise le budget restant par les émissions d’une année.","type":"nombre","unite":"ans"},{"enonce":"On attend 5 ans avant de réduire les émissions, qui restent à 40 Gt par an. Que devient le budget ?","aide":"Calcule les émissions cumulées pendant ces 5 ans.","type":"choix","options":[{"id":"a","texte":"Il ne change pas : seul le niveau des émissions annuelles compte pour le climat"},{"id":"b","texte":"Il perd 40 Gt : une seule année d’émissions est comptée dans le cumul"},{"id":"c","texte":"Il augmente de 200 Gt : les puits absorbent ce qu’on n’a pas réduit"},{"id":"d","texte":"Il perd 200 Gt : il ne reste que 300 Gt, donc l’effort à fournir ensuite est plus brutal"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"Le point à 1,5 °C se trouve au-dessus de **3 000 Gt** de CO₂ cumulé."},{"cle":{"type":"nombre","valeur":500,"tolerance":0},"affichage":"500 Gt","explication":"3 000 − 2 500 = **500 Gt**."},{"cle":{"type":"nombre","valeur":12.5,"tolerance":0},"affichage":"12,5 ans","explication":"500 ÷ 40 = **12,5 ans** : c’est très court."},{"cle":{"type":"choix","ids":["d"]},"explication":"5 × 40 = 200 Gt : le budget tombe à 500 − 200 = **300 Gt**. Retarder la baisse **consomme** le budget."}]$ex$::jsonb),
  ('c7199117-4288-5ea0-96ae-042932b4df27'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Rénover une maison","competence":"raisonner","situation":"Une famille rénove sa maison. Le gaz émet 0,23 kg de CO₂ par kWh, l’électricité du réseau 0,06 kg par kWh. Après l’isolation, une pompe à chaleur électrique produit la même chaleur avec trois fois moins d’énergie (9 000 kWh ÷ 3).","documents":[{"id":"maison","type":"tableau","titre":"Trois états de la maison","colonnes":["Situation","Énergie finale (kWh/an)","Énergie utilisée","Émissions (kg CO₂/an)"],"lignes":[["A. Départ",15000,"gaz",3450],["B. Après isolation",9000,"gaz",2070],["C. B + pompe à chaleur",3000,"électricité","?"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Touche l’énergie consommée par la maison après l’isolation.","aide":"Cherche la ligne B et la colonne des kWh.","type":"zone","document":"maison","multiple":false},{"enonce":"De quel pourcentage l’isolation réduit-elle l’énergie consommée ?","aide":"Baisse = (15 000 − 9 000) ÷ 15 000.","type":"nombre","unite":"%"},{"enonce":"Quelles sont les émissions de la situation C, en kg de CO₂ par an ?","aide":"Multiplie l’énergie en kWh par les émissions d’un kWh d’électricité.","type":"nombre","unite":"kg"},{"enonce":"Associe chaque geste au levier d’action qu’il illustre.","aide":"Sobriété : consommer moins. Efficacité : consommer mieux. Décarbonation : changer d’énergie.","type":"association","gauche":[{"id":"g0","texte":"Baisser le chauffage de 1 °C"},{"id":"g1","texte":"Isoler les combles"},{"id":"g2","texte":"Remplacer la chaudière par une pompe à chaleur électrique"},{"id":"g3","texte":"Replanter une forêt"}],"droite":[{"id":"d0","texte":"Efficacité"},{"id":"d1","texte":"Sobriété"},{"id":"d2","texte":"Décarbonation"},{"id":"d3","texte":"Puits de carbone"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Après l’isolation, la maison consomme **9 000 kWh** par an (ligne B)."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 %","explication":"6 000 ÷ 15 000 = 0,40, soit **40 %**."},{"cle":{"type":"nombre","valeur":180,"tolerance":0},"affichage":"180 kg","explication":"3 000 × 0,06 = **180 kg** de CO₂ par an."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"Baisser le chauffage = **sobriété** ; isoler = **efficacité** ; changer d’énergie = **décarbonation** ; replanter = **puits de carbone**."}]$ex$::jsonb),
  ('8aeedf56-b872-52c0-9345-38c488aee030'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Combien de CO₂ pour un kWh ?","competence":"lire-graphique","situation":"Pour comparer les filières de production d’électricité, on mesure les grammes de CO₂ émis par kilowattheure (kWh) produit, sur tout le cycle de vie.","documents":[{"id":"co2","type":"graphique","forme":"barres","titre":"Intensité carbone du kWh par filière","categories":["Charbon","Gaz","Solaire","Éolien","Nucléaire"],"series":[{"nom":"g CO₂/kWh","valeurs":[820,490,30,10,10]}],"axeY":{"titre":"Émissions","unite":"en g de CO₂ par kWh","min":0,"max":900,"pas":100},"valeurs":false,"source":"Chiffres arrondis, analyses du cycle de vie"}],"questions":[{"enonce":"Touche la filière qui émet le plus de CO₂ par kWh.","aide":"Cherche la barre la plus haute.","type":"zone","document":"co2","multiple":false},{"enonce":"De combien de grammes le charbon dépasse-t-il le gaz, par kWh ?","aide":"Soustrais les deux valeurs lues sur le graphique.","type":"nombre","unite":"g"},{"enonce":"Une centrale au gaz produit 1 000 kWh. Combien de kilogrammes de CO₂ cela représente-t-il ?","aide":"1 000 kWh × 490 g, puis convertis en kg (1 kg = 1 000 g).","type":"nombre","unite":"kg"},{"enonce":"Que permet de conclure ce graphique, sur ce seul critère ?","aide":"Compare les barres une à une, sans aller plus loin que ce qu’elles montrent.","type":"choix","options":[{"id":"a","texte":"Le gaz émet à peu près autant de CO₂ par kWh que le charbon"},{"id":"b","texte":"Le nucléaire est la filière la moins chère pour produire un kWh"},{"id":"c","texte":"L’éolien et le nucléaire émettent beaucoup moins de CO₂ par kWh que le gaz"},{"id":"d","texte":"Le solaire est la seule filière qui n’émet aucun gramme de CO₂ par kWh"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"Le **charbon** émet environ 820 g de CO₂ par kWh : la barre la plus haute."},{"cle":{"type":"nombre","valeur":330,"tolerance":10},"affichage":"330 g","explication":"820 − 490 = **330 g** de CO₂ de plus par kWh."},{"cle":{"type":"nombre","valeur":490,"tolerance":10},"affichage":"490 kg","explication":"1 000 × 490 = 490 000 g, soit **490 kg** de CO₂."},{"cle":{"type":"choix","ids":["c"]},"explication":"Sur le critère **CO₂ par kWh**, éolien et nucléaire (10 g) sont bien en dessous du gaz (490 g). Le graphique ne dit rien du coût."}]$ex$::jsonb),
  ('8aeedf56-b872-52c0-9345-38c488aee030'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une centrale qu’on décide aujourd’hui","competence":"se-reperer-temps","situation":"En 2026, un pays décide de construire une centrale électrique. Elle mettra 12 ans à être construite, puis fonctionnera 50 ans. La frise résume ce calendrier.","documents":[{"id":"calendrier","type":"frise","titre":"Le calendrier de la centrale","debut":2020,"fin":2100,"pas":10,"periodes":[{"id":"z1","debut":2026,"fin":2038,"nom":"Construction"},{"id":"z2","debut":2038,"fin":2088,"nom":"Exploitation"}],"evenements":[{"id":"z3","date":2026,"nom":"Décision"},{"id":"z4","date":2050,"nom":"Neutralité UE"}]}],"questions":[{"enonce":"Touche la période pendant laquelle la centrale produit de l’électricité.","aide":"Une centrale ne produit rien pendant qu’on la construit.","type":"zone","document":"calendrier","multiple":false},{"enonce":"En quelle année la centrale s’arrêtera-t-elle ?","aide":"Ajoute la durée de fonctionnement à l’année de mise en service.","type":"nombre"},{"enonce":"En 2050, année visée pour la neutralité carbone, combien d’années la centrale aura-t-elle encore à fonctionner ?","aide":"Soustrais 2050 à l’année d’arrêt.","type":"nombre","unite":"ans"},{"enonce":"Que montre ce calendrier sur les choix énergétiques ?","aide":"Regarde la longueur totale de la frise colorée.","type":"choix","options":[{"id":"a","texte":"Le temps de construction compte peu devant la durée de fonctionnement"},{"id":"b","texte":"Une centrale est toujours remplacée avant la fin de sa durée de vie"},{"id":"c","texte":"Une décision peut être corrigée en quelques mois si elle se révèle coûteuse"},{"id":"d","texte":"Une décision prise aujourd’hui engage le pays pendant plusieurs décennies"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La centrale produit pendant l’**exploitation**, de 2038 à 2088."},{"cle":{"type":"nombre","valeur":2088,"tolerance":0},"affichage":"2088","explication":"2038 + 50 = **2088**."},{"cle":{"type":"nombre","valeur":38,"tolerance":0},"affichage":"38 ans","explication":"2088 − 2050 = **38 ans** : cette décision de 2026 pèsera bien après 2050."},{"cle":{"type":"choix","ids":["d"]},"explication":"Entre la décision (2026) et l’arrêt (2088), il s’écoule **62 ans** : c’est l’**inertie** des choix énergétiques."}]$ex$::jsonb),
  ('8aeedf56-b872-52c0-9345-38c488aee030'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Quelle est la meilleure filière ?","competence":"argumenter","situation":"Léa prépare un exposé et affirme : « Le nucléaire est la meilleure filière, c’est évident. » Son camarade Hugo demande qu’elle le prouve avec le tableau. Les valeurs sont des ordres de grandeur arrondis, écrits pour l’exercice.","documents":[{"id":"filieres","type":"tableau","titre":"Trois filières comparées","colonnes":["Filière","CO₂ (g/kWh)","Coût complet (€/MWh)","Pilotable ?","Construction (ans)"],"lignes":[["Gaz",490,100,"oui",3],["Éolien terrestre",10,60,"non",2],["Nucléaire",10,110,"oui",12]],"enteteLignes":true,"source":"Ordres de grandeur arrondis, écrits pour l’exercice"}],"questions":[{"enonce":"Touche le coût complet le plus bas du tableau.","aide":"Compare la colonne des €/MWh.","type":"zone","document":"filieres","multiple":false},{"enonce":"De combien d’euros par MWh le nucléaire est-il plus cher que l’éolien terrestre ?","aide":"Soustrais les deux coûts complets.","type":"nombre","unite":"€/MWh"},{"enonce":"Quelle filière du tableau cumule un faible CO₂ et une production pilotable ?","aide":"Il faut cocher deux critères en même temps dans le tableau.","type":"choix","options":[{"id":"a","texte":"Le nucléaire, à 10 g de CO₂ par kWh et pilotable"},{"id":"b","texte":"L’éolien terrestre, à 10 g de CO₂ par kWh et pilotable"},{"id":"c","texte":"Aucune : toutes les filières sont intermittentes"},{"id":"d","texte":"Le gaz, pilotable mais à 10 g de CO₂ par kWh"}],"multiple":false},{"enonce":"Pourquoi le tableau ne permet-il pas de conclure que le nucléaire est « la meilleure » filière ?","aide":"Cherche un critère où le nucléaire est le dernier du classement.","type":"choix","options":[{"id":"a","texte":"Il émet plus de CO₂ par kWh que l’éolien terrestre, comme le montre le tableau"},{"id":"b","texte":"Il est le plus cher et le plus long à construire : aucune filière ne gagne partout"},{"id":"c","texte":"Le tableau ne donne aucune donnée chiffrée pour comparer les filières"},{"id":"d","texte":"Il n’est pas pilotable, contrairement au gaz, d’après la colonne prévue"}],"multiple":false}]}$ex$::jsonb,
