  ('9ca80b90-2d09-5f1a-9206-b3914212f7de'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un rythme jamais vu","competence":"calculer","situation":"À la fin de la dernière glaciation, le CO₂ a augmenté naturellement de 80 ppm. Comparons son rythme à celui d’aujourd’hui (valeurs arrondies).","documents":[{"id":"rythmes","type":"tableau","titre":"Deux hausses du CO₂","colonnes":["","Hausse (ppm)","Durée (années)","Rythme (ppm par an)"],"lignes":[["Fin de la dernière glaciation",80,8000,"?"],["Aujourd’hui",25,10,"?"]],"enteteLignes":true,"source":"Valeurs arrondies, carottes de glace et mesures directes"}],"questions":[{"enonce":"Quel était le rythme de la hausse à la fin de la dernière glaciation, en ppm par an ?","aide":"Divise la hausse (80 ppm) par la durée (8 000 ans).","type":"nombre","unite":"ppm/an"},{"enonce":"Quel est le rythme de la hausse actuelle, en ppm par an ?","aide":"Divise 25 ppm par 10 ans.","type":"nombre","unite":"ppm/an"},{"enonce":"Touche la case qui donne la durée de la hausse actuelle.","aide":"La durée s’exprime en années : cherche la ligne « Aujourd’hui ».","type":"zone","document":"rythmes","multiple":false},{"enonce":"Par quel facteur le rythme actuel dépasse-t-il celui de la fin de la glaciation ?","aide":"Divise le rythme actuel par l’ancien : 2,5 ÷ 0,01.","type":"nombre"},{"enonce":"Qu’est-ce qui distingue surtout la hausse actuelle du CO₂ de celles du passé ?","aide":"Compare les deux rythmes calculés plus haut.","type":"choix","options":[{"id":"a","texte":"Sa régularité, qui suit un cycle d’environ 100 000 ans"},{"id":"b","texte":"Sa vitesse, environ 250 fois plus grande que celle du passé"},{"id":"c","texte":"Sa lenteur, qui laisse aux milieux le temps de s’adapter"},{"id":"d","texte":"Son origine naturelle, liée aux variations de l’orbite terrestre"}],"multiple":false}]}$ex$::jsonb,
