   $ex${"titre":"« Le climat a toujours changé »","competence":"raisonner","situation":"Un élève affirme : « Le climat a déjà varié de 5 °C dans le passé, donc +1,2 °C aujourd’hui n’a rien d’inquiétant. » Vérifie avec deux documents (valeurs arrondies).","documents":[{"id":"vitesses","type":"tableau","titre":"Deux hausses de température","colonnes":["","Hausse (°C)","Durée (années)","Rythme (°C par siècle)"],"lignes":[["Fin de la dernière glaciation",5,10000,0.05],["Depuis 1850",1.2,150,"?"]],"enteteLignes":true,"source":"Valeurs arrondies"},{"id":"scenarios","type":"graphique","forme":"barres","titre":"Réchauffement à la fin du siècle","categories":["Chute rapide des émissions","Poursuite des émissions"],"series":[{"nom":"Hausse","valeurs":[1.7,4],"teinte":"encre"}],"axeY":{"titre":"Hausse de température","unite":"°C","min":0,"max":5,"pas":1},"valeurs":false,"source":"Valeurs centrales arrondies des scénarios du GIEC"}],"questions":[{"enonce":"Quel est le rythme du réchauffement depuis 1850, en °C par siècle ?","aide":"Une durée de 150 ans vaut 1,5 siècle : divise 1,2 par 1,5.","type":"nombre","unite":"°C/siècle"},{"enonce":"Par quel facteur ce rythme dépasse-t-il celui de la fin de la dernière glaciation ?","aide":"Divise 0,8 par 0,05.","type":"nombre"},{"enonce":"Touche le scénario qui conduit à plus de 3 °C de hausse à la fin du siècle.","aide":"Compare la hauteur des barres avec la graduation 3.","type":"zone","document":"scenarios","multiple":false},{"enonce":"Dans ce scénario, combien de °C s’ajoutent encore par rapport à aujourd’hui (+1,2 °C) ?","aide":"Soustrais 1,2 à la valeur de la barre.","type":"nombre","unite":"°C"},{"enonce":"Que penser de l’affirmation de l’élève ?","aide":"L’ampleur compte, mais la durée aussi : regarde le rythme.","type":"choix","options":[{"id":"a","texte":"Raisonnement faible : les 5 °C du passé ont pris 10 000 ans, alors que 1,2 °C s’est ajouté en 150 ans"},{"id":"b","texte":"Raisonnement juste : tout réchauffement est naturel puisque le climat a déjà varié dans le passé"},{"id":"c","texte":"Raisonnement juste : 5 °C dépasse 1,2 °C, donc la hausse actuelle n’a rien de particulier aujourd’hui"},{"id":"d","texte":"Raisonnement faible : avant l’ère industrielle, le climat n’avait jamais varié de façon mesurable"}],"multiple":false}]}$ex$::jsonb,
