   $ex${"titre":"L’atmosphère en cases","competence":"observer-schema","situation":"Pour simuler le climat, un modèle découpe l’atmosphère en cases appelées mailles. Sur ce schéma vu de dessus, une maille fait 50 km de côté.","documents":[{"id":"mailles","type":"schema","titre":"Vue de dessus de l’atmosphère","largeur":330,"hauteur":225,"elements":[{"forme":"texte","x":165,"y":16,"texte":"Chaque case est une maille","taille":"petit","italique":true},{"forme":"rect","x":30,"y":30,"l":90,"h":70,"id":"z1","zone":true},{"forme":"rect","x":120,"y":30,"l":90,"h":70,"id":"z2","zone":true},{"forme":"rect","x":210,"y":30,"l":90,"h":70,"id":"z3","zone":true},{"forme":"rect","x":30,"y":100,"l":90,"h":70,"id":"z4","zone":true},{"forme":"rect","x":120,"y":100,"l":90,"h":70,"id":"z5","zone":true},{"forme":"rect","x":210,"y":100,"l":90,"h":70,"id":"z6","zone":true},{"forme":"ellipse","cx":165,"cy":62,"rx":22,"ry":11,"teinte":"ciel","motif":"plein"},{"forme":"texte","x":165,"y":88,"texte":"nuage","taille":"petit"},{"forme":"ligne","de":[30,190],"a":[120,190],"fleche":"deux"},{"forme":"texte","x":75,"y":208,"texte":"50 km","taille":"petit"}]}],"questions":[{"enonce":"Touche la maille qui contient le nuage.","aide":"Le nuage est dessiné dans la case du haut, au milieu.","type":"zone","document":"mailles","multiple":false},{"enonce":"Une région carrée de 1 000 km de côté est découpée en mailles de 50 km de côté. Combien de mailles faut-il ?","aide":"Il y en a 1 000 ÷ 50 dans chaque direction : multiplie ce nombre par lui-même.","type":"nombre"},{"enonce":"Le nuage est bien plus petit que la maille. Que fait le modèle ?","aide":"Un nuage ne peut pas être calculé dans le détail à cette échelle.","type":"choix","options":[{"id":"a","texte":"Il agrandit la maille pour qu’elle contienne tout le nuage"},{"id":"b","texte":"Il le représente de façon approchée, par un paramétrage"},{"id":"c","texte":"Il calcule précisément le trajet de chaque gouttelette du nuage"},{"id":"d","texte":"Il ignore tout ce qui est plus petit qu’une maille"}],"multiple":false},{"enonce":"Remets dans l’ordre les étapes d’une simulation.","aide":"On prépare, on calcule, on répète, puis on vérifie.","type":"ordre","items":[{"id":"a","texte":"Dans chaque maille, on résout les équations de la physique"},{"id":"b","texte":"On découpe l’atmosphère en mailles"},{"id":"c","texte":"On répète le calcul, pas de temps après pas de temps"},{"id":"d","texte":"On compare le résultat au climat réellement mesuré"}]}]}$ex$::jsonb,
