   $ex${"titre":"Le tri des candidatures","competence":"analyser-document","situation":"Une entreprise entraîne un logiciel à trier des candidatures à partir de ses anciens recrutements. Le logiciel apprend à reproduire les décisions passées.","documents":[{"id":"recrut","type":"tableau","titre":"Données d’entraînement","colonnes":["","Candidatures","Retenues","Taux de retenue (%)"],"lignes":[["Hommes",800,240,"?"],["Femmes",200,40,"?"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Touche le nombre de candidatures de femmes dans les données d’entraînement.","aide":"Cherche la ligne « Femmes », colonne « Candidatures ».","type":"zone","document":"recrut","multiple":false},{"enonce":"Quel est le taux de retenue des hommes, en % ?","aide":"Divise 240 par 800, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Quel est le taux de retenue des femmes, en % ?","aide":"Divise 40 par 200, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Le logiciel reproduit ces taux. Sur 500 nouvelles candidatures de femmes, combien en retient-il ?","aide":"Calcule 20 % de 500.","type":"nombre"},{"enonce":"D’où vient le biais de ce logiciel ?","aide":"Le logiciel reproduit ce qu’on lui a montré.","type":"choix","options":[{"id":"a","texte":"D’une intention du logiciel de défavoriser certaines candidates volontairement"},{"id":"b","texte":"De la puissance de calcul, trop faible pour traiter mille dossiers à la fois"},{"id":"c","texte":"Des données d’entraînement, qui reflètent des décisions passées inégales"},{"id":"d","texte":"Du langage de programmation, qui favorise certains profils de candidats"}],"multiple":false}]}$ex$::jsonb,
