pe":"zone","document":"arbre","multiple":true},{"enonce":"Combien d’appels de f l’arbre contient-il au total, f(4) compris ?","aide":"Compte les nœuds, niveau par niveau : 1, puis 2, puis 4…","type":"nombre"},{"enonce":"Combien de fois l’appel f(1) est-il lancé ?","aide":"Regarde les feuilles de l’arbre.","type":"nombre"},{"enonce":"Que renvoie f(4) ?","aide":"f(4) = f(3) + f(2), avec f(0) = 0 et f(1) = 1.","type":"choix","options":[{"id":"a","texte":"5"},{"id":"b","texte":"3"},{"id":"c","texte":"4"},{"id":"d","texte":"2"}],"multiple":false},{"enonce":"Le nombre d’appels suit la même règle : appels(n) = 1 + appels(n − 1) + appels(n − 2). Sachant qu’il y en a 5 pour f(3) et 9 pour f(4), combien y en a-t-il pour f(5) ?","aide":"Additionne 1, 9 et 5.","type":"nombre"}]}$ex$::jsonb,
