  ('de0e2799-f5d2-5807-b9fa-436674669227'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La fusion de deux piles de cartes","competence":"programmer","situation":"Dans un tri fusion, la dernière étape consiste à fusionner deux listes déjà triées. Sacha écrit la fonction et suit son exécution avec A = [2, 7, 9] et B = [3, 4, 10].","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"La fonction fusion","auteur":"Programme écrit pour l’exercice","blocs":["def fusion(A, B):","    R = []","    i = 0","    j = 0","    while i < len(A) and j < len(B):","        if A[i] <= B[j]:","            R.append(A[i])","            i = i + 1","        else:","            R.append(B[j])","            j = j + 1","    return R + A[i:] + B[j:]","print(fusion([2, 7, 9], [3, 4, 10]))"]},{"id":"t","type":"tableau","titre":"Suivi des trois premiers tours","colonnes":["Tour","i","j","Valeur ajoutée à R"],"lignes":[[1,0,0,2],[2,1,0,3],[3,1,1,"?"]],"enteteLignes":false,"source":"Tableau de suivi écrit pour l’exercice"}],"questions":[{"enonce":"Quelle valeur est ajoutée à R au tour 3 ? (On compare A[1] et B[1].)","aide":"Compare 7 et 4 : lequel est le plus petit ?","type":"nombre"},{"enonce":"Combien de tours la boucle while fait-elle en tout ?","aide":"Continue le tableau : à chaque tour, i ou j augmente de 1.","type":"nombre"},{"enonce":"Quand la boucle s’arrête, combien de valeurs reste-t-il à recopier avec A[i:] + B[j:] ?","aide":"Regarde où en sont i et j : une des deux listes est épuisée.","type":"nombre"},{"enonce":"Que s’affiche-t-il à l’écran ?","aide":"La fusion de deux listes triées est elle-même triée.","type":"choix","options":[{"id":"a","texte":"[2, 7, 9, 3, 4, 10]"},{"id":"b","texte":"[2, 3, 7, 4, 9, 10]"},{"id":"c","texte":"[2, 3, 4, 7, 9, 10]"},{"id":"d","texte":"[2, 3, 4, 7, 10, 9]"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"Au tour 3, i = 1 et j = 1 : on compare A[1] = 7 et B[1] = 4. **4** est plus petit, c’est lui qui est ajouté."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5","explication":"Tour 4 : 7 est ajouté ; tour 5 : 9 est ajouté. Alors i vaut 3 et la boucle s’arrête : **5 tours**."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1","explication":"i vaut 3 (A est épuisée) et j vaut 2 : il reste B[2:] = [10], soit **1 valeur**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les valeurs sortent dans l’ordre 2, 3, 4, 7, 9 puis 10 (recopié à la fin) : **[2, 3, 4, 7, 9, 10]**."}]$ex$::jsonb),
  ('de0e2799-f5d2-5807-b9fa-436674669227'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Élever au carré plutôt que multiplier","competence":"calculer","situation":"Pour calculer 3 puissance n, Maëlle refuse de faire n multiplications. Sa fonction calcule d’abord la puissance pour n // 2, puis élève le résultat au carré : c’est l’exponentiation rapide.","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"La fonction puiss","auteur":"Programme écrit pour l’exercice","blocs":["def puiss(x, n):","    if n == 0:","        return 1","    z = puiss(x, n // 2)","    z = z * z","    if n % 2 == 1:","        z = x * z","    return z","print(puiss(3, 5))"]},{"id":"t","type":"tableau","titre":"Ce que renvoie chaque appel","colonnes":["Appel","Il renvoie"],"lignes":[["puiss(3, 0)",1],["puiss(3, 1)","?"],["puiss(3, 2)","?"],["puiss(3, 5)","?"]],"enteteLignes":false,"source":"Tableau de suivi écrit pour l’exercice"}],"questions":[{"enonce":"Combien d’appels puiss(3, 5) lance-t-elle au total, le premier compris ? (Les valeurs de n sont 5, 2, 1, 0.)","aide":"À chaque appel, n est divisé par 2 (quotient entier).","type":"nombre"},{"enonce":"Que renvoie puiss(3, 1) ? (Ici z = puiss(3, 0) = 1.)","aide":"z devient 1 × 1, puis n est impair : z est multiplié par x.","type":"nombre"},{"enonce":"Que renvoie puiss(3, 2) ? (Ici z = puiss(3, 1) = 3.)","aide":"z devient 3 × 3 ; n = 2 est pair.","type":"nombre"},{"enonce":"Que s’affiche-t-il pour puiss(3, 5) ?","aide":"z = 9 × 9 = 81, puis n = 5 est impair.","type":"choix","options":[{"id":"a","texte":"81"},{"id":"b","texte":"243"},{"id":"c","texte":"125"},{"id":"d","texte":"15"}],"multiple":false},{"enonce":"Pour n = 1024, n est divisé par 2 à chaque appel : 1024, 512, 256… jusqu’à 0. Combien d’appels puiss(3, 1024) lance-t-elle ?","aide":"Combien de fois peut-on diviser 1024 par 2 pour arriver à 1 ? Ajoute ensuite l’appel de n = 0.","type":"nombre"}]}$ex$::jsonb,
