  ('59c810ed-0027-5c5e-8c5c-725ccf3d3000'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Fibonacci avec un carnet","competence":"programmer","situation":"Camille veut éviter de refaire les mêmes calculs. Elle ajoute à sa fonction un dictionnaire memo, où elle note chaque résultat dès qu’elle l’a trouvé.","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"Fibonacci mémoïsé","auteur":"Programme écrit pour l’exercice","blocs":["memo = {}","def fib(n):","    if n < 2:","        return n","    if n in memo:","        return memo[n]","    memo[n] = fib(n - 1) + fib(n - 2)","    return memo[n]","print(fib(6))"]},{"id":"t","type":"tableau","titre":"Les premiers termes","colonnes":["n","0","1","2","3","4","5"],"lignes":[["fib(n)",0,1,1,2,"?",5]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Quelle valeur manque dans le tableau, pour n = 4 ?","aide":"Chaque terme est la somme des deux précédents.","type":"nombre"},{"enonce":"Que s’affiche-t-il quand on lance le programme ?","aide":"fib(6) = fib(5) + fib(4).","type":"nombre"},{"enonce":"Que fait la ligne « if n in memo » suivie de « return memo[n] » ?","aide":"Que contient memo quand n a déjà été calculé ?","type":"choix","options":[{"id":"a","texte":"Elle vérifie que n est bien un nombre entier positif avant de faire le calcul"},{"id":"b","texte":"Elle renvoie tout de suite le résultat déjà noté, au lieu de refaire le calcul"},{"id":"c","texte":"Elle efface le carnet pour recommencer chaque calcul depuis le début à chaque fois"},{"id":"d","texte":"Elle arrête le programme dès que n a déjà été utilisé une fois dans un appel"}],"multiple":false}]}$ex$::jsonb,
