  ('59c810ed-0027-5c5e-8c5c-725ccf3d3000'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Les chemins de la grille","competence":"modeliser","situation":"Une fourmi part du coin d’une grille et ne peut aller que vers la droite ou vers le bas. On note chemins(i, j) le nombre de chemins pour atteindre la case située i lignes plus bas et j colonnes plus à droite.","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"La fonction chemins","auteur":"Programme écrit pour l’exercice","blocs":["def chemins(i, j):","    if i == 0 or j == 0:","        return 1","    return chemins(i - 1, j) + chemins(i, j - 1)"]},{"id":"t","type":"tableau","titre":"Le tableau des valeurs","colonnes":["","j = 0","j = 1","j = 2","j = 3"],"lignes":[["i = 0",1,1,1,1],["i = 1",1,2,3,4],["i = 2",1,3,"?",10],["i = 3",1,4,10,"?"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Que vaut chemins(2, 2), la case manquante de la ligne i = 2 ?","aide":"Additionne la case juste au-dessus et la case juste à gauche.","type":"nombre"},{"enonce":"Que vaut chemins(3, 3), la dernière case du tableau ?","aide":"Additionne 10 (au-dessus) et 10 (à gauche).","type":"nombre"},{"enonce":"Sans mémoriser, combien d’appels de chemins le calcul de chemins(2, 2) lance-t-il, le premier compris ? (Il y en a 5 pour chemins(1, 2) et pour chemins(2, 1).)","aide":"Compte 1 pour l’appel lui-même, plus les deux sous-arbres.","type":"nombre"},{"enonce":"Avec un dictionnaire qui retient les résultats, chaque case n’est calculée qu’une fois. Combien de cases différentes chemins(2, 2) demande-t-il (la case (0, 0) n’est jamais appelée) ?","aide":"Le tableau 3 × 3 contient 9 cases : laquelle n’est jamais utilisée ?","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"chemins(2, 2) = chemins(1, 2) + chemins(2, 1) = 3 + 3 = **6**."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20","explication":"chemins(3, 3) = chemins(2, 3) + chemins(3, 2) = 10 + 10 = **20**."},{"cle":{"type":"nombre","valeur":11,"tolerance":0},"affichage":"11","explication":"1 + 5 + 5 = **11 appels**, alors que le tableau ne contient que quelques cases."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8","explication":"Les cases (i, j) avec i et j de 0 à 2, sauf (0, 0) : **8 cases**, contre 11 appels sans mémoire."}]$ex$::jsonb),
