   $ex${"titre":"CAD dans ABRACADABRA","competence":"programmer","situation":"Bastien cherche le motif « CAD » dans le mot ABRACADABRA. Sa fonction essaie chaque position, une par une, en comparant des morceaux de texte.","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"La recherche naïve","auteur":"Programme écrit pour l’exercice","blocs":["def cherche(texte, motif):","    n = len(texte)","    m = len(motif)","    for i in range(n - m + 1):","        if texte[i:i + m] == motif:","            return i","    return -1","print(cherche(\"ABRACADABRA\", \"CAD\"))"]},{"id":"t","type":"tableau","titre":"Les premiers alignements","colonnes":["i","Morceau lu","Égal à CAD ?"],"lignes":[[0,"ABR","non"],[1,"BRA","non"],[2,"RAC","non"],[3,"ACA","non"],[4,"CAD","?"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Que s’affiche-t-il ?","aide":"La fonction renvoie la première position où le morceau est égal au motif.","type":"nombre"},{"enonce":"Le texte fait 11 lettres et le motif 3. Combien de positions la boucle peut-elle essayer au maximum ? (range(n - m + 1))","aide":"Calcule 11 − 3 + 1.","type":"nombre"},{"enonce":"Que renvoie cherche(\"ABRACADABRA\", \"ABRA\") ?","aide":"La fonction s’arrête à la première occurrence.","type":"choix","options":[{"id":"a","texte":"0"},{"id":"b","texte":"7"},{"id":"c","texte":"4"},{"id":"d","texte":"-1"}],"multiple":false}]}$ex$::jsonb,
