  ('5a014766-7f54-5f3d-a80f-8cec79ecd48c'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La table de Knuth-Morris-Pratt","competence":"analyser-document","situation":"Pour ne jamais revenir en arrière dans le texte, l’algorithme de Knuth-Morris-Pratt prépare une table à partir du motif ABABAC : pour chaque préfixe du motif, la longueur du plus long bout qui est à la fois début et fin de ce préfixe.","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"Le calcul de la table","auteur":"Programme écrit pour l’exercice","blocs":["def prefixes(m):","    P = [0]","    k = 0","    for i in range(1, len(m)):","        while k > 0 and m[i] != m[k]:","            k = P[k - 1]","        if m[i] == m[k]:","            k = k + 1","        P.append(k)","    return P","print(prefixes(\"ABABAC\"))"]},{"id":"t","type":"tableau","titre":"La table du motif ABABAC","colonnes":["Motif","A","B","A","B","A","C"],"lignes":[["Préfixe lu","A","AB","ABA","ABAB","ABABA","ABABAC"],["Longueur k",0,0,1,2,"?",0]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Quelle longueur manque pour le préfixe ABABA ? (Son plus long début qui est aussi une fin est ABA.)","aide":"Compte les lettres de ABA.","type":"nombre"},{"enonce":"Que signifie la valeur 2 pour le préfixe ABAB ?","aide":"Cherche un début et une fin identiques dans ABAB.","type":"choix","options":[{"id":"a","texte":"Le plus long début de ABAB qui est aussi une fin de ABAB est AB, de longueur 2"},{"id":"b","texte":"Le préfixe ABAB apparaît deux fois dans le texte que l’on est en train de lire"},{"id":"c","texte":"Le préfixe ABAB contient exactement deux lettres A et deux lettres B à la suite"},{"id":"d","texte":"Le motif ABABAC est décalé de deux positions dès qu’une lettre du texte diffère"}],"multiple":false},{"enonce":"On a reconnu ABAB (4 lettres) dans le texte, puis la lettre suivante ne convient pas. Combien de lettres du motif reste-t-il reconnues en repartant ? (Lis la table pour le préfixe ABAB.)","aide":"Regarde la valeur k du préfixe ABAB.","type":"nombre"},{"enonce":"Que renvoie prefixes(\"AABA\") ?","aide":"Calcule la valeur pour A, AA, AAB puis AABA.","type":"choix","options":[{"id":"a","texte":"[0, 1, 2, 3]"},{"id":"b","texte":"[0, 0, 1, 0]"},{"id":"c","texte":"[0, 1, 0, 1]"},{"id":"d","texte":"[0, 1, 1, 2]"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"Pour ABABA, le plus long bout à la fois début et fin est ABA, de longueur **3**."},{"cle":{"type":"choix","ids":["a"]},"explication":"ABAB commence par **AB** et finit par **AB** : c’est le plus long bout commun au début et à la fin, de longueur 2."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"La table donne **2** pour ABAB : on repart avec AB déjà reconnu, sans revenir en arrière dans le texte."},{"cle":{"type":"choix","ids":["c"]},"explication":"A : 0 ; AA : 1 (A) ; AAB : 0 ; AABA : 1 (A). Le programme renvoie **[0, 1, 0, 1]**."}]$ex$::jsonb),
