e","document":"reseau","multiple":false},{"enonce":"Quel est le coût total du chemin choisi par RIP ?","aide":"Additionne les coûts des deux liens du chemin R1 – R2 – R5.","type":"nombre"},{"enonce":"Quel est le coût total du chemin que choisit OSPF, celui de plus petit coût ?","aide":"Essaie R1 – R3 – R4 – R5.","type":"nombre"},{"enonce":"Pourquoi RIP choisit-il ici un chemin plus lent que celui d’OSPF ?","aide":"Quel critère RIP utilise-t-il ?","type":"choix","options":[{"id":"a","texte":"Il refuse tout chemin de plus de deux sauts, qu’il juge trop long pour les paquets"},{"id":"b","texte":"Il ne compte que les sauts et ignore le coût de chaque lien traversé par les paquets"},{"id":"c","texte":"Il additionne les coûts mais se trompe d’un lien quand le réseau contient cinq routeurs"},{"id":"d","texte":"Il choisit toujours le chemin passant par le routeur qui porte le plus petit numéro"}],"multiple":false}]}$ex$::jsonb,
