   $ex${"titre":"Trois inquiétudes, trois garanties","competence":"analyser-document","situation":"Trois élèves racontent ce qui leur est arrivé en ligne. Chacun a perdu une garantie de sécurité différente : confidentialité, intégrité ou authenticité.","documents":[{"id":"t","type":"tableau","titre":"Ce qui s’est passé","colonnes":["Cas","Récit"],"lignes":[["A","Un inconnu lit le message que Lina envoie depuis le Wi-Fi d’un café."],["B","Le montant d’un virement est modifié pendant son transfert."],["C","Le site ressemble à celui d’une banque, mais ce n’en est pas un."]],"enteteLignes":false,"source":"Situations imaginées pour l’exercice"}],"questions":[{"enonce":"Touche le cas où c’est l’authenticité qui n’est pas garantie.","aide":"Avec qui parle-t-on vraiment ?","type":"zone","document":"t","multiple":false},{"enonce":"Associe chaque cas à la garantie perdue.","aide":"A : qui lit ? B : qui a modifié ? C : qui parle ?","type":"association","gauche":[{"id":"g0","texte":"Cas A"},{"id":"g1","texte":"Cas B"},{"id":"g2","texte":"Cas C"}],"droite":[{"id":"d0","texte":"Authenticité"},{"id":"d1","texte":"Intégrité"},{"id":"d2","texte":"Confidentialité"}]},{"enonce":"Quel outil permet de détecter que le montant du cas B a été modifié ?","aide":"Quelle fonction change entièrement si le message change ?","type":"choix","options":[{"id":"a","texte":"Un pare-feu qui filtre les connexions arrivant sur l’ordinateur de Lina"},{"id":"b","texte":"Un VPN qui masque l’adresse du réseau depuis lequel Lina est connectée"},{"id":"c","texte":"Un mot de passe plus long pour protéger la connexion au site de la banque"},{"id":"d","texte":"Une empreinte du message, calculée avec une fonction de hachage comme SHA-256"}],"multiple":false}]}$ex$::jsonb,
