  ('b27cf8d8-353f-5f48-9f92-be3f9bedac5d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Qui a la clé ?","competence":"raisonner","situation":"Alice écrit à Bob. Éve, sur le réseau, intercepte tout ce qui passe. Alice et Bob utilisent le chiffrement asymétrique : chacun possède une clé publique, que tout le monde connaît, et une clé privée, gardée secrète.","documents":[{"id":"chaine","type":"chaine","disposition":"ligne","titre":"Le trajet du message","source":"Schéma écrit pour l’exercice","noeuds":[{"id":"z1","texte":"Alice","emoji":"👩"},{"id":"z2","texte":"Message chiffré","emoji":"✉️"},{"id":"z3","texte":"Bob","emoji":"👨"}],"liens":[{"de":"z1","a":"z2","texte":"envoie"},{"de":"z2","a":"z3","texte":"reçoit"}]}],"questions":[{"enonce":"Associe chaque opération à la clé utilisée.","aide":"La clé publique se diffuse à tous ; la clé privée ne sert qu’à son propriétaire.","type":"association","gauche":[{"id":"g0","texte":"Chiffrer un message pour Bob"},{"id":"g1","texte":"Déchiffrer ce message"},{"id":"g2","texte":"Signer un message"},{"id":"g3","texte":"Vérifier une signature"}],"droite":[{"id":"d0","texte":"Clé privée de Bob"},{"id":"d1","texte":"Clé privée de l’émetteur"},{"id":"d2","texte":"Clé publique de l’émetteur"},{"id":"d3","texte":"Clé publique de Bob"}]},{"enonce":"Éve intercepte le message chiffré. Pourquoi ne peut-elle pas le lire ?","aide":"Quelle clé permet de déchiffrer un message chiffré avec la clé publique de Bob ?","type":"choix","options":[{"id":"a","texte":"Elle n’a pas de certificat, ce qui lui interdit d’ouvrir n’importe quel message"},{"id":"b","texte":"Elle ne possède pas la clé privée de Bob, seule capable de déchiffrer ce message"},{"id":"c","texte":"Elle ne connaît pas la clé publique de Bob, qui reste secrète pour tout le monde"},{"id":"d","texte":"Le message ne passe jamais par le réseau, il est remis directement à Bob en main"}],"multiple":false},{"enonce":"Range dans l’ordre les étapes d’une connexion HTTPS.","aide":"D’abord on vérifie qui on a en face, puis on partage un secret, puis on l’utilise.","type":"ordre","items":[{"id":"a","texte":"Navigateur et serveur s’accordent sur une clé de session grâce au chiffrement asymétrique"},{"id":"b","texte":"Le navigateur vérifie le certificat du serveur"},{"id":"c","texte":"Les données échangées ensuite sont chiffrées avec cette clé de session symétrique"}]},{"enonce":"Pour envoyer un film de 2 Go à Bob, que chiffre-t-on avec le chiffrement asymétrique (RSA) ?","aide":"Lequel des deux chiffrements est le plus rapide pour de gros volumes ?","type":"choix","options":[{"id":"a","texte":"Rien du tout, car un film de cette taille ne peut pas être chiffré sur le réseau"},{"id":"b","texte":"Le film en entier, car le chiffrement asymétrique est le plus rapide des deux"},{"id":"c","texte":"Seulement la clé de session, le film étant chiffré avec cette clé en symétrique"},{"id":"d","texte":"Seulement l’empreinte du film, car le chiffrement ne protège que l’intégrité"}],"multiple":false}]}$ex$::jsonb,
