  ('b27cf8d8-353f-5f48-9f92-be3f9bedac5d'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La base de mots de passe volée","competence":"analyser-document","situation":"Un site stocke les mots de passe de ses membres sous forme d’empreintes SHA-256 (tronquées ici à 8 caractères pour la lecture). Un pirate vient de copier la table. Le site a d’abord stocké les empreintes sans sel, puis avec un sel différent pour chaque membre.","documents":[{"id":"t","type":"tableau","titre":"Extrait de la table volée","colonnes":["Membre","Sel","Empreinte sans sel","Empreinte avec sel"],"lignes":[["Ana","k7","e93e24c1","30fbe823"],["Ben","m2","e93e24c1","7b34c8ee"],["Cléo","p9","f2d81a26","ee3add85"]],"enteteLignes":false,"source":"Empreintes SHA-256 tronquées, membres imaginés pour l’exercice"}],"questions":[{"enonce":"Touche les deux empreintes sans sel qui sont identiques.","aide":"Compare les valeurs de la colonne « Empreinte sans sel ».","type":"zone","document":"t","multiple":true},{"enonce":"Que peut déduire le pirate en lisant seulement la colonne « sans sel » ?","aide":"Une fonction de hachage donne-t-elle toujours la même empreinte pour la même entrée ?","type":"choix","options":[{"id":"a","texte":"Que les deux membres sont une seule personne qui possède deux comptes"},{"id":"b","texte":"Que deux membres ont choisi le même mot de passe, sans même le connaître"},{"id":"c","texte":"Que les deux membres ont demandé le changement de leur mot de passe"},{"id":"d","texte":"Que le mot de passe de ces deux membres est le premier de sa liste"}],"multiple":false},{"enonce":"Avec le sel, les empreintes d’Ana et de Ben sont différentes alors que leur mot de passe est le même. Pourquoi ?","aide":"Que hache-t-on : le mot de passe seul, ou le sel suivi du mot de passe ?","type":"choix","options":[{"id":"a","texte":"Le sel est différent, donc le texte qui passe dans la fonction de hachage l’est aussi"},{"id":"b","texte":"Le sel chiffre l’empreinte avec une clé, qui est différente pour chaque membre"},{"id":"c","texte":"Le sel change le mot de passe lui-même, qui n’est donc plus le même pour les deux"},{"id":"d","texte":"La fonction de hachage est aléatoire et donne un résultat différent à chaque appel"}],"multiple":false},{"enonce":"Une empreinte SHA-256 complète compte 256 bits, et un caractère hexadécimal en représente 4. Combien de caractères hexadécimaux fait-elle ?","aide":"Divise 256 par 4.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2","r1c2"]},"explication":"Ana et Ben ont la **même empreinte sans sel** : une même entrée donne toujours la même empreinte."},{"cle":{"type":"choix","ids":["b"]},"explication":"Deux mots de passe identiques donnent deux empreintes identiques : le pirate **repère les mots de passe partagés**, et un seul craqué en révèle plusieurs."},{"cle":{"type":"choix","ids":["a"]},"explication":"On hache « sel + mot de passe » : les textes sont différents, donc les empreintes aussi. Une table d’empreintes **précalculée** devient inutilisable."},{"cle":{"type":"nombre","valeur":64,"tolerance":0},"affichage":"64","explication":"256 ÷ 4 = **64 caractères** hexadécimaux, quelle que soit la taille du message haché."}]$ex$::jsonb),
  ('897a1e61-6e4d-5956-ad5b-0a61efec0a8f'::uuid, 1, 1, 5, 20, 3,
