   $ex${"titre":"Trois tables pour la médiathèque","competence":"modeliser","situation":"Marine sépare son grand tableau en trois tables : lecteur, livre et emprunt. Un lecteur peut emprunter plusieurs livres, et un livre est emprunté par plusieurs lecteurs au fil du temps.","documents":[{"id":"t","type":"tableau","titre":"Le schéma relationnel (# marque une clé étrangère)","colonnes":["Table","Attributs"],"lignes":[["lecteur","id (clé primaire), nom, adresse"],["livre","id (clé primaire), titre, auteur"],["emprunt","#lecteur_id, #livre_id, date_emprunt"]],"enteteLignes":false,"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Touche le nom de la table qui relie les lecteurs et les livres.","aide":"Cherche la table qui ne contient que des clés étrangères et une date.","type":"zone","document":"t","multiple":false},{"enonce":"Combien de clés étrangères la table emprunt contient-elle ?","aide":"Compte les attributs précédés de #.","type":"nombre"},{"enonce":"Quelle est la cardinalité entre lecteur et livre ?","aide":"Une table peut-elle porter seule la clé de l’autre ?","type":"choix","options":[{"id":"a","texte":"Plusieurs à un : plusieurs lecteurs partagent un seul livre, emprunté par tous"},{"id":"b","texte":"Un à un : chaque lecteur emprunte un seul livre, qui n’est emprunté que par lui"},{"id":"c","texte":"Plusieurs à plusieurs : un lecteur emprunte plusieurs livres et inversement"},{"id":"d","texte":"Un à plusieurs : un lecteur emprunte plusieurs livres, mais un livre un seul lecteur"}],"multiple":false},{"enonce":"Un emprunt est enregistré avec livre_id = 99, alors qu’aucun livre n’a cet identifiant. Quelle contrainte est violée ?","aide":"La clé étrangère pointe vers quoi ?","type":"choix","options":[{"id":"a","texte":"La contrainte de domaine : un identifiant de livre doit être un nombre entier"},{"id":"b","texte":"La clé primaire : l’identifiant 99 est déjà utilisé par le lecteur de la table"},{"id":"c","texte":"L’unicité : deux emprunts ne peuvent pas avoir la même valeur de clé étrangère"},{"id":"d","texte":"L’intégrité référentielle : une clé étrangère doit viser un enregistrement existant"}],"multiple":false}]}$ex$::jsonb,
