   $ex${"titre":"Le club de sport","competence":"modeliser","situation":"Un club gère des entraîneurs, des cours et des adhérents. Un entraîneur dirige plusieurs cours, mais un cours a un seul entraîneur. Un adhérent suit plusieurs cours, et un cours accueille plusieurs adhérents.","documents":[{"id":"club","type":"schema","titre":"Les trois entités et leurs relations","largeur":320,"hauteur":230,"source":"Schéma écrit pour l’exercice","elements":[{"forme":"rect","x":95,"y":15,"l":130,"h":40,"arrondi":6,"texte":"Entraîneur","id":"z1","zone":true},{"forme":"rect","x":95,"y":95,"l":130,"h":40,"arrondi":6,"texte":"Cours","id":"z2","zone":true},{"forme":"rect","x":95,"y":175,"l":130,"h":40,"arrondi":6,"texte":"Adhérent","id":"z3","zone":true},{"forme":"ligne","de":[160,55],"a":[160,95]},{"forme":"ligne","de":[160,135],"a":[160,175]},{"forme":"texte","x":146,"y":68,"texte":"1","ancre":"milieu","gras":true},{"forme":"texte","x":146,"y":90,"texte":"n","ancre":"milieu","gras":true},{"forme":"texte","x":146,"y":148,"texte":"n","ancre":"milieu","gras":true},{"forme":"texte","x":146,"y":170,"texte":"n","ancre":"milieu","gras":true},{"forme":"texte","x":218,"y":79,"texte":"dirige","ancre":"milieu","taille":"petit","italique":true},{"forme":"texte","x":218,"y":159,"texte":"suit","ancre":"milieu","taille":"petit","italique":true}]}],"questions":[{"enonce":"Touche la table qui doit porter la clé étrangère vers l’entraîneur.","aide":"La clé étrangère se place du côté « plusieurs ».","type":"zone","document":"club","multiple":false},{"enonce":"Pour la relation « suit » entre adhérent et cours, que faut-il créer ?","aide":"Ni l’adhérent ni le cours ne peuvent porter seuls la clé de l’autre.","type":"choix","options":[{"id":"a","texte":"Une clé étrangère dans la table cours seulement"},{"id":"b","texte":"Une table de jonction portant les deux clés étrangères"},{"id":"c","texte":"Une clé étrangère dans la table adhérent seulement"},{"id":"d","texte":"Une seule table qui fusionne adhérents et cours"}],"multiple":false},{"enonce":"Combien de tables contient le schéma final, table de jonction comprise ?","aide":"Trois tables d’entités, plus la table de jonction.","type":"nombre"},{"enonce":"Quelle clé primaire convient à la table inscription(#adherent_id, #cours_id, date_inscription) ?","aide":"Un même adhérent peut suivre plusieurs cours : une colonne seule suffit-elle ?","type":"choix","options":[{"id":"a","texte":"La seule colonne date_inscription, qui change à chaque inscription"},{"id":"b","texte":"Le couple (adherent_id, cours_id), qui identifie chaque inscription"},{"id":"c","texte":"La seule colonne adherent_id, qui est propre à chaque adhérent"},{"id":"d","texte":"Aucune : une table de jonction n’a pas besoin de clé primaire"}],"multiple":false}]}$ex$::jsonb,
