  ('a6cbec5f-3b81-5309-82ac-890fb4bfafbf'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le piège des cases vides","competence":"raisonner","situation":"Une professeure a saisi les notes d’un devoir : deux élèves absents n’ont pas de note. Dans la base, une note absente vaut NULL, qui n’est ni zéro ni une chaîne vide.","documents":[{"id":"t","type":"tableau","titre":"La table eleve","colonnes":["nom","note"],"lignes":[["Ana",12],["Bo","NULL"],["Cy",8],["Di",15],["Eli","NULL"]],"enteteLignes":false,"source":"Données imaginées pour l’exercice"},{"id":"req","type":"texte","genre":"consigne","titre":"Quatre requêtes","auteur":"Programme écrit pour l’exercice","blocs":["SELECT COUNT(*) FROM eleve","SELECT COUNT(note) FROM eleve","SELECT AVG(note) FROM eleve","SELECT nom FROM eleve WHERE note = NULL"]}],"questions":[{"enonce":"Quel nombre renvoie la première requête, SELECT COUNT(*) ?","aide":"COUNT(*) compte toutes les lignes.","type":"nombre"},{"enonce":"Quel nombre renvoie la deuxième requête, SELECT COUNT(note) ?","aide":"COUNT(colonne) ne compte que les valeurs renseignées.","type":"nombre"},{"enonce":"Que renvoie la troisième requête, SELECT AVG(note) ?","aide":"Les NULL entrent-ils dans la somme et dans le nombre de valeurs ?","type":"choix","options":[{"id":"a","texte":"Exactement 7 : les valeurs NULL comptent pour zéro dans le calcul"},{"id":"b","texte":"NULL : une seule valeur NULL rend la moyenne entière inconnue"},{"id":"c","texte":"Environ 11,67 : les valeurs NULL sont ignorées dans le calcul"},{"id":"d","texte":"Environ 8,75 : les NULL et la meilleure note sont écartées"}],"multiple":false},{"enonce":"Combien de lignes la quatrième requête, WHERE note = NULL, renvoie-t-elle ?","aide":"Une comparaison avec NULL renvoie « inconnu », même NULL = NULL.","type":"nombre"}]}$ex$::jsonb,
