  ('a6cbec5f-3b81-5309-82ac-890fb4bfafbf'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un index et une vue","competence":"raisonner","situation":"L’association sportive d’un lycée garde 1 000 000 d’inscriptions dans une table. Elle ajoute un index sur la colonne interrogée tous les jours, et crée une vue pour le secrétariat, qui ne doit pas voir les moyennes des élèves.","documents":[{"id":"t","type":"tableau","titre":"Nombre de lectures au maximum pour une recherche","colonnes":["Lignes de la table","Sans index","Avec index"],"lignes":[["1 000","1 000",10],["1 000 000","1 000 000",20],["1 000 000 000","1 000 000 000","?"]],"enteteLignes":false,"source":"Ordres de grandeur, index en arbre équilibré"},{"id":"sql","type":"texte","genre":"consigne","titre":"La vue et le droit","auteur":"Programme écrit pour l’exercice","blocs":["CREATE VIEW eleve_public AS","    SELECT nom, classe_id FROM eleve","GRANT SELECT ON eleve_public TO secretariat"]}],"questions":[{"enonce":"Combien de lectures, à peu près, pour une recherche avec index sur un milliard de lignes ? (Le nombre double à peu près quand la table est multipliée par 1 000, en ajoutant 10.)","aide":"Regarde comment passent les valeurs de la colonne « Avec index » : +10 à chaque fois.","type":"nombre"},{"enonce":"Pourquoi ne crée-t-on pas un index sur toutes les colonnes ?","aide":"Que doit faire la base à chaque insertion ?","type":"choix","options":[{"id":"a","texte":"Chaque index ralentit les insertions et occupe de la place sur le disque"},{"id":"b","texte":"Un index rend les recherches plus lentes quand il y en a plusieurs"},{"id":"c","texte":"La base refuse de créer un index sur une colonne qui n’est pas une clé"},{"id":"d","texte":"Les colonnes de type texte ne peuvent jamais être indexées par la base"}],"multiple":false},{"enonce":"Touche le mot qui donne un droit au secrétariat.","aide":"Le mot est au début de la dernière ligne.","type":"zone","document":"sql","multiple":false},{"enonce":"Quelle information du secrétariat reste hors de sa portée, dans la table eleve(id, nom, classe_id, moyenne) ?","aide":"Compare les colonnes de la table et celles de la vue.","type":"choix","options":[{"id":"a","texte":"Le nom des élèves, absent de la vue eleve_public"},{"id":"b","texte":"La classe des élèves, absente de la vue eleve_public"},{"id":"c","texte":"La moyenne des élèves, absente de la vue eleve_public"},{"id":"d","texte":"Aucune : une vue donne accès à toute la table d’origine"}],"multiple":false}]}$ex$::jsonb,
