   $ex${"titre":"Le virement en deux temps","competence":"raisonner","situation":"Paul vire 50 € du compte 1 vers le compte 2. La banque regroupe les deux opérations dans une transaction, pour qu’elles réussissent ensemble ou échouent ensemble.","documents":[{"id":"sql","type":"texte","genre":"consigne","titre":"La transaction","auteur":"Programme écrit pour l’exercice","blocs":["BEGIN","UPDATE compte SET solde = solde - 50 WHERE id = 1","UPDATE compte SET solde = solde + 50 WHERE id = 2","COMMIT"]},{"id":"t","type":"tableau","titre":"Les soldes avant le virement","colonnes":["Compte","Solde (€)"],"lignes":[[1,200],[2,100]],"enteteLignes":false,"source":"Comptes imaginés pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui valide définitivement la transaction.","aide":"C’est la dernière ligne.","type":"zone","document":"sql","multiple":false},{"enonce":"Quel est le solde du compte 1 après le COMMIT, en euros ?","aide":"Retire 50 € à 200 €.","type":"nombre"},{"enonce":"Une coupure de courant arrive entre les deux UPDATE, avant le COMMIT. Quel est le solde du compte 1 quand le serveur redémarre, en euros ?","aide":"La transaction est tout ou rien.","type":"nombre"},{"enonce":"Quelle propriété ACID garantit que le virement se fait en entier ou pas du tout ?","aide":"Tout ou rien.","type":"choix","options":[{"id":"a","texte":"La cohérence"},{"id":"b","texte":"L’atomicité"},{"id":"c","texte":"L’isolation"},{"id":"d","texte":"La durabilité"}],"multiple":false}]}$ex$::jsonb,
