  ('8d5c9ba0-28e9-5b11-a1ad-06876a0996a3'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le dernier billet","competence":"analyser-document","situation":"Une billetterie en ligne garde un stock de 10 billets. Deux clients achètent un billet presque au même instant. Le tableau suit ce que chacun lit et écrit dans la base.","documents":[{"id":"t","type":"tableau","titre":"Le déroulement","colonnes":["Étape","Client 1","Client 2","Stock en base"],"lignes":[[1,"lit le stock : 10","—",10],[2,"—","lit le stock : 10",10],[3,"écrit 9","—",9],[4,"—","écrit 9",9]],"enteteLignes":false,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Touche l’étape où le client 2 écrase le travail du client 1.","aide":"C’est la dernière écriture.","type":"zone","document":"t","multiple":false},{"enonce":"Combien de billets devrait-il rester après les deux achats ?","aide":"Deux billets ont été vendus.","type":"nombre"},{"enonce":"Quelle propriété ACID n’est pas respectée ici ?","aide":"Les deux transactions auraient dû se dérouler comme si elles étaient successives.","type":"choix","options":[{"id":"a","texte":"La durabilité : la base a perdu une écriture après une panne"},{"id":"b","texte":"L’isolation : les deux transactions se sont mélangées"},{"id":"c","texte":"La cohérence : le stock est devenu négatif pendant les calculs"},{"id":"d","texte":"L’atomicité : une des deux transactions n’a pas fini"}],"multiple":false},{"enonce":"Que fait le SGBD pour éviter cette perte ?","aide":"Comment faire attendre le second client ?","type":"choix","options":[{"id":"a","texte":"Il attribue le même billet aux deux clients et prévient le vendeur"},{"id":"b","texte":"Il supprime le stock et recommence avec un nouveau de 10 billets"},{"id":"c","texte":"Il verrouille la ligne du stock : le client 2 attend la fin du client 1"},{"id":"d","texte":"Il refuse tout achat tant qu’un autre client a lu le stock avant lui"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c2"]},"explication":"À l’étape 4, le client 2 écrit **9** alors que le stock était déjà tombé à 9 : il écrase l’achat du client 1."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8","explication":"10 − 2 = **8 billets**, mais la base en affiche 9 : un achat a été perdu."},{"cle":{"type":"choix","ids":["b"]},"explication":"Deux transactions simultanées doivent donner le même résultat que deux transactions **successives** : c’est l’**isolation**, ici non respectée."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un **verrou** (ou un mécanisme de versions) oblige le client 2 à attendre que le client 1 ait terminé : il lit alors 9 et écrit 8."}]$ex$::jsonb),
