   $ex${"titre":"Chacun attend l’autre","competence":"observer-schema","situation":"Deux transactions T1 et T2 modifient deux lignes A et B. T1 a verrouillé A et demande B. T2 a verrouillé B et demande A. Le schéma montre qui détient et qui attend.","documents":[{"id":"verrous","type":"schema","titre":"Verrous détenus et demandés","largeur":330,"hauteur":240,"source":"Schéma écrit pour l’exercice","elements":[{"forme":"cercle","cx":80,"cy":50,"r":26,"texte":"T1"},{"forme":"cercle","cx":250,"cy":50,"r":26,"texte":"T2"},{"forme":"rect","x":35,"y":152,"l":90,"h":36,"arrondi":6,"texte":"Ligne A","id":"z1","zone":true},{"forme":"rect","x":205,"y":152,"l":90,"h":36,"arrondi":6,"texte":"Ligne B","id":"z2","zone":true},{"forme":"ligne","de":[80,152],"a":[80,77],"fleche":"fin"},{"forme":"ligne","de":[250,152],"a":[250,77],"fleche":"fin"},{"forme":"ligne","de":[102,66],"a":[226,154],"fleche":"fin","style":"pointilles"},{"forme":"ligne","de":[228,66],"a":[104,154],"fleche":"fin","style":"pointilles"},{"forme":"texte","x":50,"y":118,"texte":"détient","ancre":"milieu","taille":"petit"},{"forme":"texte","x":282,"y":118,"texte":"détient","ancre":"milieu","taille":"petit"},{"forme":"texte","x":165,"y":226,"texte":"Trait plein : détient le verrou · pointillés : attend","ancre":"milieu","taille":"petit","italique":true}]}],"questions":[{"enonce":"Touche la ligne dont T1 a besoin pour continuer.","aide":"T1 détient déjà A.","type":"zone","document":"verrous","multiple":false},{"enonce":"Touche la ligne dont T2 a besoin pour continuer.","aide":"T2 détient déjà B.","type":"zone","document":"verrous","multiple":false},{"enonce":"Combien de transactions sont bloquées ?","aide":"Chacune attend une ligne détenue par l’autre.","type":"nombre"},{"enonce":"Comment le SGBD sort-il de cette situation ?","aide":"Aucune des deux ne peut avancer seule.","type":"choix","options":[{"id":"a","texte":"Il détecte l’interblocage et annule l’une des deux transactions"},{"id":"b","texte":"Il supprime les deux lignes A et B pour libérer les verrous posés"},{"id":"c","texte":"Il attend indéfiniment que l’une des deux transactions finisse"},{"id":"d","texte":"Il valide les deux transactions d’office en ignorant les verrous"}],"multiple":false},{"enonce":"Comment les développeurs peuvent-ils éviter ce genre d’interblocage ?","aide":"Le cycle vient d’ordres opposés.","type":"choix","options":[{"id":"a","texte":"En supprimant l’instruction COMMIT de chacune des deux transactions"},{"id":"b","texte":"En lançant les deux transactions sur deux ordinateurs différents"},{"id":"c","texte":"En ajoutant une troisième ligne C que personne n’aurait à verrouiller"},{"id":"d","texte":"En demandant toujours les verrous dans le même ordre, A puis B"}],"multiple":false}]}$ex$::jsonb,
