 moy fonctionne-t-il alors que moy n’est pas une colonne de la table ?","aide":"Que fait le mot-clé AS sur une colonne calculée ?","type":"choix","options":[{"id":"a","texte":"AS a créé un alias, qu’ORDER BY peut réutiliser"},{"id":"b","texte":"Le SGBD trie d’abord par la clé primaire puis par moy"},{"id":"c","texte":"moy est ajoutée comme colonne permanente de eleve"},{"id":"d","texte":"ORDER BY recalcule AVG sans tenir compte de GROUP BY"}],"multiple":false}]}$ex$::jsonb,
