  ('7c861ef3-ddbc-5d34-b037-3d89686d18a2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux façons d’additionner","competence":"programmer","situation":"Yanis écrit deux fonctions qui donnent le même résultat : la première avec une boucle et une variable qui change, la seconde avec des appels récursifs. Il se demande de quel paradigme relève chacune.","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"Les deux sommes de Yanis","auteur":"Programme écrit pour l’exercice","blocs":["def somme_a(L):","    s = 0","    for x in L:","        s = s + x","    return s","def somme_b(L):","    if L == []:","        return 0","    return L[0] + somme_b(L[1:])","print(somme_a([4, 7, 1]), somme_b([4, 7, 1]))"]}],"questions":[{"enonce":"Combien d’appels de somme_b sont lancés pour somme_b([4, 7, 1]) ? Compte le premier et celui de la liste vide.","aide":"Les listes successives sont de longueur 3, 2, 1, puis 0.","type":"nombre"},{"enonce":"Laquelle des deux fonctions est écrite dans le style fonctionnel ?","aide":"Le style fonctionnel remplace la boucle par la récursivité et ne modifie pas de variable.","type":"choix","options":[{"id":"a","texte":"somme_a, car elle calcule le même total avec une variable s"},{"id":"b","texte":"somme_b, car elle n’a ni boucle ni variable modifiée"},{"id":"c","texte":"Aucune, car Python n’accepte que le paradigme impératif"},{"id":"d","texte":"Les deux, car elles renvoient la même valeur pour [4, 7, 1]"}],"multiple":false},{"enonce":"Que renvoie somme_b([]) ?","aide":"Regarde la condition de la deuxième ligne de somme_b.","type":"nombre"},{"enonce":"Associe chaque paradigme à son terrain de prédilection.","aide":"Relis l’usage qui se dégage de chaque définition.","type":"association","gauche":[{"id":"g0","texte":"Impératif"},{"id":"g1","texte":"Fonctionnel"},{"id":"g2","texte":"Objet"},{"id":"g3","texte":"Événementiel"}],"droite":[{"id":"d0","texte":"Algorithme court, performance critique"},{"id":"d1","texte":"Modélisation d’un domaine durable"},{"id":"d2","texte":"Transformation de données, tests fiables"},{"id":"d3","texte":"Interface, réseau, temps réel"}]}]}$ex$::jsonb,
