  ('7103cc87-d376-547e-be05-ae7c6bf68edc'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quand deux modules ont le même nom","competence":"analyser-document","situation":"Deux modules de Léo définissent chacun une fonction aire : dans cercle.py, l’aire approchée d’un disque (avec pi pris égal à 3) ; dans carre.py, l’aire d’un carré de côté c. Il les importe tous les deux dans son programme.","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"Les deux modules et le programme principal","auteur":"Programme écrit pour l’exercice","blocs":["# Fichier cercle.py","def aire(r):","    return 3 * pow(r, 2)","# Fichier carre.py","def aire(c):","    return c * c","# Programme principal","from cercle import *","from carre import *","print(aire(2))"]},{"id":"formes","type":"tableau","titre":"Trois formes d’importation","colonnes":["Forme d’importation","Appel de la fonction"],"lignes":[["import cercle","cercle.aire(2)"],["from cercle import aire","aire(2)"],["from cercle import *","aire(2)"]],"enteteLignes":false,"source":"Données écrites pour l’exercice"}],"questions":[{"enonce":"Quel nombre affiche le programme principal ?","aide":"Quelle définition de aire est la dernière à avoir été importée ?","type":"nombre"},{"enonce":"Touche la forme d’importation à proscrire.","aide":"Laquelle ne dit pas d’où viennent les noms qu’elle apporte ?","type":"zone","document":"formes","multiple":false},{"enonce":"Avec import cercle puis import carre, que vaudrait cercle.aire(2) ?","aide":"Le préfixe cercle. désigne sans ambiguïté la fonction du module cercle.","type":"nombre"}]}$ex$::jsonb,
