  ('1d4cb955-20d8-5b83-b147-e87b2dce18b2'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Ce que disent les commentaires","competence":"analyser-document","situation":"Sacha relit un programme de facturation écrit par un camarade. Chaque ligne importante porte un commentaire, mais tous n’ont pas la même utilité.","documents":[{"id":"comm","type":"tableau","titre":"Quatre lignes commentées","colonnes":["Code","Commentaire"],"lignes":[["i = i + 1","# ajoute 1 à i"],["for ligne in lignes[1:]:","# on saute la 1re ligne : c'est l'en-tête du fichier"],["return total","# renvoie total"],["prix = p * 1.055","# taux réduit : c'est un livre"]],"enteteLignes":false,"source":"Données écrites pour l’exercice"}],"questions":[{"enonce":"Touche le commentaire qui explique pourquoi on saute la première ligne.","aide":"Cherche le commentaire qui parle du fichier, pas de la boucle.","type":"zone","document":"comm","multiple":false},{"enonce":"Classe ces commentaires : utile (il explique le pourquoi) ou inutile (il répète le code) ?","aide":"Un bon commentaire apporte une information que le code ne dit pas.","type":"categories","categories":[{"id":"c0","texte":"Utile"},{"id":"c1","texte":"Inutile"}],"items":[{"id":"i0","texte":"renvoie total"},{"id":"i1","texte":"on saute la 1re ligne : c’est l’en-tête du fichier"},{"id":"i2","texte":"taux réduit : c’est un livre"},{"id":"i3","texte":"ajoute 1 à i"}]},{"enonce":"Le taux 1.055 est recopié à la main dans douze fonctions. Quelle amélioration s’impose ?","aide":"Si le taux change, combien de lignes faudra-t-il modifier ?","type":"choix","options":[{"id":"a","texte":"Le ranger dans une constante nommée TAUX_LIVRE utilisée partout"},{"id":"b","texte":"Le remplacer par 1.06 dans toutes les fonctions pour arrondir"},{"id":"c","texte":"Le recopier aussi dans un commentaire au-dessus de chaque fonction"},{"id":"d","texte":"Ajouter à chaque ligne un commentaire qui répète la valeur 1.055"}],"multiple":false}]}$ex$::jsonb,
