  ('1d4cb955-20d8-5b83-b147-e87b2dce18b2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois tests, un bug qui se cache","competence":"analyser-document","situation":"Yanis écrit une fonction qui renvoie le plus grand élément d’une liste, puis la teste sur trois listes. Il note ce qu’il attendait et ce que la fonction a renvoyé.","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"La fonction maximum","auteur":"Programme écrit pour l’exercice","blocs":["def maximum(L):","    m = 0","    for x in L:","        if x > m:","            m = x","    return m"]},{"id":"tests","type":"tableau","titre":"Les trois tests de Yanis","colonnes":["Entrée","Attendu","Obtenu"],"lignes":[["[3, 9, 4]",9,9],["[5]",5,5],["[-2, -7]",-2,0]],"enteteLignes":false,"source":"Données écrites pour l’exercice"}],"questions":[{"enonce":"Touche la case qui montre que la fonction échoue.","aide":"Compare la colonne Attendu et la colonne Obtenu.","type":"zone","document":"tests","multiple":false},{"enonce":"Quelle est la cause du résultat 0 ?","aide":"Que vaut m si aucun élément de la liste n’est plus grand que 0 ?","type":"choix","options":[{"id":"a","texte":"m commence à 0, alors que les nombres peuvent tous être négatifs"},{"id":"b","texte":"La fonction ne renvoie rien quand la liste contient deux éléments"},{"id":"c","texte":"La comparaison x > m devrait être écrite x < m"},{"id":"d","texte":"La boucle for ne lit jamais le dernier élément de la liste"}],"multiple":false},{"enonce":"Que renvoie maximum([-5]) ?","aide":"Pour la liste d’un seul élément négatif, recommence le raisonnement de la question précédente.","type":"nombre"},{"enonce":"Les deux premiers tests sont réussis. Que prouvent-ils ?","aide":"Dijkstra : les tests montrent la présence de bugs, jamais leur absence.","type":"choix","options":[{"id":"a","texte":"Que la fonction est correcte pour les listes positives"},{"id":"b","texte":"Que la fonction est correcte pour toutes les listes"},{"id":"c","texte":"Que la fonction marche sur ces cas, pas sur tous les cas"},{"id":"d","texte":"Que la fonction est assez rapide pour de longues listes"}],"multiple":false}]}$ex$::jsonb,
