  ('92393036-4e09-5fae-964d-0807562ef5bc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Enquête sur une moyenne trop basse","competence":"raisonner","situation":"Maëlys affiche la moyenne de trois notes : 10, 20 et 30. Elle s’attendait à 20 et obtient un nombre plus petit, sans aucun message d’erreur. Elle mène l’enquête.","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"La fonction de Maëlys","auteur":"Programme écrit pour l’exercice","blocs":["def moyenne(L):","    total = 0","    for i in range(1, len(L)):","        total = total + L[i]","    return total / len(L)","print(moyenne([10, 20, 30]))"]}],"questions":[{"enonce":"Quel nombre affiche le programme ? Arrondis au dixième.","aide":"La boucle commence à l’indice 1 : quelles notes additionne-t-elle ? Puis divise par 3.","type":"nombre"},{"enonce":"Quel est le plus petit cas qui reproduit l’erreur ? Que renvoie moyenne([5]) ?","aide":"Avec une seule note, l’indice 1 n’existe pas : que fait range(1, 1) ?","type":"nombre"},{"enonce":"Remets dans l’ordre les cinq temps de la méthode de correction.","aide":"On ne corrige qu’après avoir compris ; et on finit par un test.","type":"ordre","items":[{"id":"a","texte":"Localiser la zone où l’état devient incorrect"},{"id":"b","texte":"Comprendre la cause, pas seulement le symptôme"},{"id":"c","texte":"Reproduire l’erreur avec le plus petit cas possible"},{"id":"d","texte":"Ajouter un test qui échouait avant la correction"},{"id":"e","texte":"Corriger le code"}]},{"enonce":"Quelle écriture de la boucle corrige le bug ?","aide":"Les indices d’une liste de n éléments vont de 0 à n - 1.","type":"choix","options":[{"id":"a","texte":"for i in range(0, len(L), 2):"},{"id":"b","texte":"for i in range(len(L)):"},{"id":"c","texte":"for i in range(1, len(L) + 1):"},{"id":"d","texte":"for i in range(len(L) - 1):"}],"multiple":false},{"enonce":"Après correction, que renvoie moyenne([12, 14, 16, 18]) ?","aide":"Additionne les quatre notes puis divise par 4.","type":"nombre"}]}$ex$::jsonb,
