   $ex${"titre":"Deux comptes, deux frais","competence":"analyser-document","situation":"Une banque prélève des frais à chaque retrait. Le compte courant prend 2 euros ; le compte épargne, qui hérite du compte courant, n’en prend aucun. Nina suit les soldes de deux clients.","documents":[{"id":"cls","type":"texte","genre":"consigne","titre":"Les deux classes","auteur":"Programme écrit pour l’exercice","blocs":["class Compte:","    def __init__(self, solde):","        self.solde = solde","    def frais(self):","        return 2","    def retirer(self, s):","        self.solde = self.solde - s - self.frais()","class Epargne(Compte):","    def frais(self):","        return 0"]},{"id":"use","type":"texte","genre":"consigne","titre":"Deux retraits de 10 euros","auteur":"Programme écrit pour l’exercice","blocs":["a = Compte(100)","b = Epargne(100)","a.retirer(10)","b.retirer(10)","print(a.solde, b.solde)"]}],"questions":[{"enonce":"Quel solde affiche a.solde ?","aide":"Le retrait de 10 euros s’accompagne des frais du compte courant.","type":"nombre"},{"enonce":"Quel solde affiche b.solde ?","aide":"Epargne redéfinit frais : que renvoie cette version ?","type":"nombre"},{"enonce":"Pourquoi b.retirer(10) donne-t-il un résultat différent, alors que retirer n’est écrite que dans Compte ?","aide":"Dans retirer, quel objet est self quand on appelle b.retirer(10) ?","type":"choix","options":[{"id":"a","texte":"self.frais() appelle la version qui correspond au type réel de l’objet"},{"id":"b","texte":"b n’est pas un Compte, donc il n’utilise pas la méthode retirer"},{"id":"c","texte":"Python copie retirer dans Epargne en la modifiant au passage"},{"id":"d","texte":"Epargne remplace entièrement la méthode retirer de Compte"}],"multiple":false},{"enonce":"Une classe Livret hérite de Compte et redéfinit frais pour renvoyer 1. Quel est le solde d’un Livret de 100 euros après retirer(10) ?","aide":"Il hérite de retirer et utilise ses propres frais.","type":"nombre"},{"enonce":"Associe chaque situation au mécanisme qui la traduit.","aide":"« est un » et « a un » ne se traduisent pas de la même façon.","type":"association","gauche":[{"id":"g0","texte":"Un compte épargne est un compte"},{"id":"g1","texte":"Une voiture a un moteur"},{"id":"g2","texte":"Même appel, comportement propre à chaque objet"},{"id":"g3","texte":"Changer l’intérieur sans casser l’extérieur"}],"droite":[{"id":"d0","texte":"Polymorphisme"},{"id":"d1","texte":"Héritage"},{"id":"d2","texte":"Composition"},{"id":"d3","texte":"Encapsulation"}]}]}$ex$::jsonb,
