e","cx":139,"cy":104,"r":15,"texte":"4","id":"z12","zone":true},{"forme":"cercle","cx":191,"cy":142,"r":15,"texte":"6","id":"z13","zone":true},{"forme":"cercle","cx":243,"cy":180,"r":15,"texte":"7","id":"z14","zone":true},{"forme":"cercle","cx":295,"cy":218,"r":15,"texte":"8","id":"z15","zone":true}],"source":"Arbre écrit pour l’exercice"}],"questions":[{"enonce":"Combien de nœuds visite la recherche de 7 dans l’arbre A ?","aide":"Descends de la racine : 7 est plus grand ou plus petit que 8, puis que 3, puis que 6 ?","type":"nombre"},{"enonce":"Quelle est la hauteur de l’arbre B ?","aide":"Compte les arêtes entre la racine et la feuille la plus profonde.","type":"nombre"},{"enonce":"Combien de nœuds visite la recherche de 8 dans l’arbre B ?","aide":"Dans B, chaque comparaison écarte un seul nœud.","type":"nombre"},{"enonce":"Pourquoi l’arbre B a-t-il cette forme de peigne ?","aide":"Où se place chaque nouvelle valeur quand elle est plus grande que toutes les précédentes ?","type":"choix","options":[{"id":"a","texte":"Ses valeurs ont été insérées déjà triées, en croissant"},{"id":"b","texte":"Ses valeurs ont été insérées dans un ordre aléatoire"},{"id":"c","texte":"Ses valeurs sont plus grandes que celles de l’arbre A"},{"id":"d","texte":"Un arbre de recherche doit toujours avoir cette forme"}],"multiple":false},{"enonce":"Un arbre binaire de hauteur 4 contient au plus combien de nœuds ? Utilise la formule 2^(h+1) - 1.","aide":"Calcule 2^5 puis retire 1.","type":"nombre"}]}$ex$::jsonb,
